def count_rectangles_with_sum(a, s):
    n = len(s)
    count = 0

    # Precompute the product matrix b
    b = [[int(s[i]) * int(s[j]) for j in range(n)] for i in range(n)]

    # Iterate over all possible pairs of rows
    for x in range(n):
        for y in range(x, n):
            # Use a hash map to store the sum of elements in the current row segment
            sum_map = {0: 1}
            current_sum = 0

            # Iterate over all possible pairs of columns
            for z in range(n):
                for t in range(z, n):
                    # Calculate the sum of the rectangle (x, z) to (y, t)
                    if z == 0:
                        current_sum = sum(b[i][t] for i in range(x, y + 1))
                    else:
                        current_sum += sum(b[i][t] for i in range(x, y + 1))

                    # Check if there is a previous sum that matches the required sum
                    if current_sum - a in sum_map:
                        count += sum_map[current_sum - a]

                    # Update the hash map with the current sum
                    if current_sum in sum_map:
                        sum_map[current_sum] += 1
                    else:
                        sum_map[current_sum] = 1

    return count

